// Build lookup: key = "cardA|laneA|cardB|laneB" -> SynergyEntry
// Order within a pair doesn't matter — we store both directions.
const synergyMap = new Map<string, SynergyEntry>();

for (const [a, laneA, b, laneB, wins, total] of SYNERGY_DATA) {
  // Store both orderings
  const key1 = `${a}|${laneA}|${b}|${laneB}`;
  const key2 = `${b}|${laneB}|${a}|${laneA}`;
  const entry: SynergyEntry = { cardA: a, laneA, cardB: b, laneB, wins, total };
  synergyMap.set(key1, entry);
  synergyMap.set(key2, entry);
}

export function getSynergy(
  cardA: string,
  laneA: Lane,
  cardB: string,
  laneB: Lane
): SynergyEntry | null {
  const key = `${cardA}|${laneA}|${cardB}|${laneB}`;
  return synergyMap.get(key) ?? null;
}

export function getAllSynergies(): SynergyEntry[] {
  // Return unique entries (deduplicate by sorting card IDs)
  const seen = new Set<string>();
  const result: SynergyEntry[] = [];
  for (const entry of synergyMap.values()) {
    const canonical =
      entry.cardA < entry.cardB
        ? `${entry.cardA}|${entry.laneA}|${entry.cardB}|${entry.laneB}`
        : `${entry.cardB}|${entry.laneB}|${entry.cardA}|${entry.laneA}`;
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(entry);
    }
  }
  return result;
}
